WITH "m0" AS ( INSERT INTO "public"."mutation_item" AS "s" ( "id" , "title" , "score" , "owner_id" ) VALUES ( $1 , $2 , $3 , $4 ) ON CONFLICT ON CONSTRAINT "mutation_item_pkey" DO NOTHING RETURNING "s" AS "t0" , NULL::tid AS "k0" , CAST(CASE WHEN "s"."score" >= $5 THEN '1' ELSE 'rusuna: permission check failed' || left( "s"."ctid" ::text, 0) END AS integer) AS "check__constraint" ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ) SELECT (SELECT row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "t0"."title" AS "title" , "t0"."score" AS "score" , "t0"."note" AS "note" ) AS "%")) FROM "r0" AS "t0" )
